// robots.txt, generated by Next at /robots.txt.
//
// Everything behind the login is disallowed, not because it is secret (it is protected by
// auth, not by this file) but because a crawler that follows /dashboard gets a redirect to
// the login form and then reports a pile of near-identical thin pages. That is how a small
// site teaches Google that most of it is worthless.
//
// What is left allowed is the set of pages that actually say something to a stranger: the
// landing page, the disclaimer, and the two doors in.
//
// /welcome is disallowed rather than left open because it is a permanent redirect to "/".
// There is nothing to crawl there and no reason to spend the budget finding that out.

const PRIVATE = [
  "/dashboard",
  "/plan",
  "/log",
  "/progress",
  "/settings",
  "/leaderboard",
  "/nutrition",
  "/assessment",
  "/onboarding",
  "/blockend",
  "/type",
  "/fallback",
  "/feedback",
  "/forgot-password",
  "/reset-password",
  "/welcome",
];

export default function robots() {
  const site = process.env.NEXT_PUBLIC_SITE_URL || "https://vaeonfitness.com";

  return {
    rules: [
      {
        userAgent: "*",
        allow: "/",
        disallow: PRIVATE.map(function (p) {
          return p + "/";
        }).concat(PRIVATE),
      },
    ],
    sitemap: site + "/sitemap.xml",
    host: site,
  };
}
